/* Open Cube OS - WP-10-chinese_support
 * File: chinese/chinese_font.h
 * Purpose: GB2312 16x16 bitmap font - management and lookup API.
 *
 * The embedded font (chinese_font_data.c, generated by
 * tools/gen_chinese_font.py from GNU Unifont) carries:
 *   - 6763 hanzi   (GB2312 zones 16..87), compact 32 B/glyph = 216416 B
 *   - 682 symbols  (GB2312 zones 1..9),   compact 32 B/glyph =  21824 B
 *   - zone-slot -> compact-index tables and a sorted Unicode -> index
 *     reverse table for UTF-8 input paths.
 *
 * Every glyph is 16 rows x 2 bytes, bit7 of each byte = leftmost pixel
 * (same row packing as the built-in screen_font8x16 ASCII table).
 *
 * Driver-API style extension (the numbered L1 set stays closed at
 * 1-138): these interfaces are single-listed per the WP-10 precedent.
 */
#ifndef OC_CHINESE_FONT_H
#define OC_CHINESE_FONT_H

#include "types.h"

#define CHINESE_FONT_GLYPH_W      16
#define CHINESE_FONT_GLYPH_H      16
#define CHINESE_FONT_GLYPH_BYTES  32   /* 16 rows x 2 bytes */
#define CHINESE_FONT_HANZI_COUNT  6763
#define CHINESE_FONT_SYMBOL_COUNT 682
#define CHINESE_FONT_UTO_COUNT    7445 /* 6763 hanzi + 682 symbols */

/* 3.0.0-WP04 G11b: the six raw tables are gzip-wrapped in
 * chinese_font_data.c (identity-window relief - the kernel image must
 * end below 0x400000; see gen_font_gz.py).  chinese_font.c inflates
 * the stream into one kmalloc'd buffer lazily on first glyph lookup;
 * the macros below address the sections inside that buffer in the
 * fixed order the generator emits them. */
#define CHINESE_FONT_ZONE_INDEX_LEN    6768 /* (zone-16)*94+(wei-1)     */
#define CHINESE_FONT_SYMBOL_INDEX_LEN   846 /* (zone-1)*94+(wei-1)     */
#define CHINESE_FONT_GZ_RAW_LEN        298138u
#define CHINESE_FONT_GZ_OFF_GLYPHS           0u
#define CHINESE_FONT_GZ_OFF_SYMBOLS \
    (CHINESE_FONT_GZ_OFF_GLYPHS + \
     (CHINESE_FONT_HANZI_COUNT * CHINESE_FONT_GLYPH_BYTES))
#define CHINESE_FONT_GZ_OFF_ZONE_INDEX \
    (CHINESE_FONT_GZ_OFF_SYMBOLS + \
     (CHINESE_FONT_SYMBOL_COUNT * CHINESE_FONT_GLYPH_BYTES))
#define CHINESE_FONT_GZ_OFF_SYMBOL_INDEX \
    (CHINESE_FONT_GZ_OFF_ZONE_INDEX + (CHINESE_FONT_ZONE_INDEX_LEN * 2))
#define CHINESE_FONT_GZ_OFF_UTO_GB \
    (CHINESE_FONT_GZ_OFF_SYMBOL_INDEX + (CHINESE_FONT_SYMBOL_INDEX_LEN * 2))
#define CHINESE_FONT_GZ_OFF_IDX_TO_UNICODE \
    (CHINESE_FONT_GZ_OFF_UTO_GB + (2 * CHINESE_FONT_UTO_COUNT * 2))
/* CHINESE_FONT_GZ_OFF_IDX_TO_UNICODE + (CHINESE_FONT_UTO_COUNT * 2)
 * == CHINESE_FONT_GZ_RAW_LEN (checked at compile time in
 * chinese_font.c). */

/* Max runtime-registered font slots: slot 0 is the embedded font. */
#define CHINESE_FONT_MAX_SLOTS    4

/* Opaque font handle: slot id returned by load/register, or -1. */
typedef int chinese_font_handle_t;

typedef struct chinese_font_stats {
    u32         hanzi_count;      /* glyphs in the hanzi table            */
    u32         symbol_count;     /* glyphs in the symbol table           */
    u32         glyph_bytes;      /* 32                                   */
    u32         hanzi_data_size;  /* hanzi_count * glyph_bytes            */
    u32         symbol_data_size; /* symbol_count * glyph_bytes           */
    u32         slots_used;       /* registered slots (embedded included) */
    u32         lookups;          /* total lookup calls                   */
    u32         misses;           /* lookups that resolved to no glyph    */
    const char* source;           /* e.g. "embedded-unifont-16x16"        */
} chinese_font_stats_t;

/* Initialize the font subsystem and load the embedded font into slot 0.
 * Idempotent: calling twice returns 0 without side effects. */
int  chinese_font_init(void);

/* Shutdown: drop all runtime slots. Slot 0 stays registered (const data);
 * counters reset. Returns 0 on success. */
int  chinese_font_shutdown(void);

/* Ensure the embedded font is loaded (load slot 0 if needed).
 * Returns the slot id (0) or a negative errno. */
int  chinese_font_load(void);

/* Register a runtime font from memory. `hanzi`/`symbols` point to
 * count*32 bytes of packed 16x16 bitmaps; `uto_gb` is a flat array of
 * {u16 unicode, u16 idx} pairs (idx bit15 = symbol table) sorted by
 * unicode, `uto_count` pairs total. The data is referenced, not copied.
 * Returns a new slot id >= 0, or -1 (table full) / -2 (bad args). */
int  chinese_font_load_mem(const char* name,
                           const u8* hanzi, u32 hanzi_count,
                           const u8* symbols, u32 symbol_count,
                           const u16* uto_gb, u32 uto_count);

/* Unload a runtime slot. Slot 0 (embedded) cannot be unloaded: -5.
 * Unknown slot: -3. */
int  chinese_font_unload(chinese_font_handle_t slot);

/* Zone/wei lookup: GB2312 zone (16..87 hanzi, 1..9 symbols) and wei
 * (1..94) -> compact glyph index, or -1 when the slot is invalid or the
 * slot is a gap in the GB2312 table. */
int  chinese_font_lookup(chinese_font_handle_t slot, u32 zone, u32 wei);
/* Unicode lookup: BMP codepoint -> compact glyph index (bit15 set =
 * symbol table), or -1 when unmapped. */
int  chinese_font_lookup_unicode(chinese_font_handle_t slot, u32 cp);

/* Compact index -> 32-byte bitmap, or NULL when the index is invalid.
 * Bit15 of idx selects the symbol table (see lookup_unicode). */
const u8* chinese_font_get_bitmap(chinese_font_handle_t slot, int idx);

/* Convenience: Unicode -> bitmap in one step (NULL when unmapped). */
const u8* chinese_font_get_bitmap_unicode(chinese_font_handle_t slot, u32 cp);

/* Glyph metrics of this subsystem: always 16 x 16, stride 2 bytes.
 * Returns 0 on success, -2 when any out pointer is NULL. */
int  chinese_font_get_metrics(u32* w, u32* h, u32* stride);

/* Compact index -> Unicode codepoint (bit15 of idx = symbol table), or
 * 0xFFFFFFFF when unmapped. Needed by GB2312 -> Unicode decoding. */
u32  chinese_font_index_to_unicode(chinese_font_handle_t slot, int idx);

/* Raw index-table accessors (3.0.0-WP04 G11b: the tables live in the
 * gzip container now; these force the lazy inflate and return the
 * kmalloc'd copies - encoding.c walks them for GB2312 encoding).
 * Returns NULL only when the heap-backed inflate failed. */
const u16* chinese_font_zone_index_table(void);
const u16* chinese_font_symbol_index_table(void);

/* Fill a stats snapshot. Returns 0 on success, -2 when out is NULL. */
int  chinese_font_status(chinese_font_stats_t* out);

#endif /* OC_CHINESE_FONT_H */
